SourceCode.Declaration:
public abstract class ISMBatchableTelemetryBase extends ISMTelemetryBase
{

}

Method.Source:
public void initialize()
{
    super();


    if (logParams.RecId == 0)
    {
        // Setup for telemetry is being created, setup for batchable telemetry needs to be added
        if (logParams.validateWrite())
        {
            logParams.insert();

            ISMBatchableTelemetryParameterSetup batchableTelemetryParameterSetup;
            this.initializeBatchableParameterSetup(batchableTelemetryParameterSetup);
            if (batchableTelemetryParameterSetup.validateWrite())
            {
                batchableTelemetryParameterSetup.insert();
            }
            ISMBatchableTelemetryStatusTable::initRecords(batchableTelemetryParameterSetup);
        }

    }
}
